// 构建双向 Map（使用闭包避免全局开销）
function buildMaps(): { s2t: Map<string, string>; t2s: Map<string, string> } {
  const s2t = new Map<string, string>();
  const t2s = new Map<string, string>();
  for (const [s, t] of SIMP_TO_TRAD_PAIRS) {
    if (s && t) {
      s2t.set(s, t);
      t2s.set(t, s);
    }
  }
  return { s2t, t2s };
}

let _cache: { s2t: Map<string, string>; t2s: Map<string, string> } | null = null;
function getMaps() {
  if (!_cache) _cache = buildMaps();
  return _cache;
}

/**
 * 简体 → 繁体。未收录字符原样保留。
 */
export function toTraditional(text: string): string {
  const { s2t } = getMaps();
  if (!text) return '';
  let out = '';
  for (let i = 0; i < text.length; i++) {
    const ch = text.charAt(i);
    out += s2t.get(ch) || ch;
  }
  return out;
}

/**
 * 繁体 → 简体。未收录字符原样保留。
 */
export function toSimplified(text: string): string {
  const { t2s } = getMaps();
  if (!text) return '';
  let out = '';
  for (let i = 0; i < text.length; i++) {
    const ch = text.charAt(i);
    out += t2s.get(ch) || ch;
  }
  return out;
}

/**
 * 返回收录的条目数（便于调试/功能边界提示）
 */
export function getDictSize(): number {
  return SIMP_TO_TRAD_PAIRS.length;
}
